CREATE TABLE IF NOT EXISTS projects (id VARCHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, created_at VARCHAR(40) NOT NULL, deleting BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS specifications (id VARCHAR(36) PRIMARY KEY, project_id VARCHAR(36) NOT NULL REFERENCES projects(id) ON DELETE CASCADE, version INTEGER NOT NULL, payload TEXT NOT NULL, source TEXT NOT NULL, UNIQUE(project_id, version));
CREATE TABLE IF NOT EXISTS plans (id VARCHAR(36) PRIMARY KEY, specification_id VARCHAR(36) NOT NULL REFERENCES specifications(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plan_revisions (id VARCHAR(36) PRIMARY KEY, plan_id VARCHAR(36) NOT NULL REFERENCES plans(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS executions (id VARCHAR(36) PRIMARY KEY, plan_id VARCHAR(36) NOT NULL REFERENCES plans(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analyses (execution_id VARCHAR(36) PRIMARY KEY REFERENCES executions(id) ON DELETE CASCADE, payload TEXT NOT NULL);
